import{_ as l,a0 as r,w as o,s as d,ao as p,I as i,a1 as t,A as a,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"将你的安卓手机屏幕投射到 Linux | LCTT x X-CMD","titleTemplate":false,"description":"将你的安卓手机屏幕投射到 Linux | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将你的安卓手机屏幕投射到 Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将你的安卓手机屏幕投射到 Linux | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210308 Cast your Android device with a Raspberry Pi","title":"将你的安卓手机屏幕投射到 Linux","tag":"202104","desc":""},"relativePath":"202104/20210308 Cast your Android device with a Raspberry Pi.md","filePath":"[post].md"}'),u={name:"202104/20210308 Cast your Android device with a Raspberry Pi.md"};function b(g,s,y,m,h,f){const e=r("Link");return o(),d("div",null,[s[36]||(s[36]=p('<h1 id="将你的安卓手机屏幕投射到-linux" tabindex="-1">将你的安卓手机屏幕投射到 Linux <a class="header-anchor" href="#将你的安卓手机屏幕投射到-linux" aria-label="Permalink to “将你的安卓手机屏幕投射到 Linux”">​</a></h1><blockquote><p>使用 Scrcpy 可以把你的手机屏幕变成一个“应用”，与在树莓派或任何其他基于 Linux 的设备上的应用一起运行。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202104/20/162346alpbh85xz26xcb5h.jpg" alt=""></p><p>要远离我们日常使用的电子产品是很难的。在熙熙攘攘的现代生活中，我想确保我不会错过手机屏幕上弹出的来自朋友和家人的重要信息。我也很忙，不希望迷失在令人分心的事情中，但是拿起手机并且回复信息往往会使我分心。</p><p>更糟糕的是，有很多的设备。幸运地是，大多数的设备（从功能强大的笔记本电脑到甚至不起眼的树莓派）都可以运行 Linux。因为它们运行的是 Linux，所以我为一种设置找到的解决方案几乎都适用于其他设备。</p><h3 id="普遍适用" tabindex="-1">普遍适用 <a class="header-anchor" href="#普遍适用" aria-label="Permalink to “普遍适用”">​</a></h3><p>我想要一种无论我使用什么屏幕，都能统一我生活中不同来源的数据的方法。</p><p>我决定通过把手机屏幕复制到电脑上来解决这个问题。本质上，我把手机变成了一个“应用”，可以和我所有的其他程序运行在一起。这有助于我将注意力集中在桌面上，防止我走神，并使我更容易回复紧急通知。</p><p>听起来有吸引力吗？你也可以这样做。</p><h3 id="设置-scrcpy" tabindex="-1">设置 Scrcpy <a class="header-anchor" href="#设置-scrcpy" aria-label="Permalink to “设置 Scrcpy”">​</a></h3>',10)),i("p",null,[t(e,{href:"https://github.com/Genymobile/scrcpy"},{default:a(()=>[...s[0]||(s[0]=[n("Scrcpy",-1)])]),_:1}),s[1]||(s[1]=n(" 俗称屏幕复制（Screen Copy），是一个开源的屏幕镜像工具，它可以在 Linux、Windows 或者 macOS 上显示和控制安卓设备。安卓设备和计算机之间的通信主要是通过 USB 连接和",-1)),s[2]||(s[2]=i("ruby",null,[n("安卓调试桥"),i("rt",null,"Android Debug Bridge")],-1)),s[3]||(s[3]=n("（ADB）。它使用 TCP/IP，且不需要 root 权限访问。",-1))]),s[37]||(s[37]=p(`<p>Scrcpy 的设置和配置非常简单。如果你正在运行 Fedora，你可以从 COPR 仓库安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf copr enable zeno/scrcpy</span></span>
<span class="line"><span>$ sudo dnf install scrcpy -y</span></span></code></pre></div><p>在 Debian 或者 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install scrcpy</span></span></code></pre></div>`,4)),i("p",null,[s[5]||(s[5]=n("你也可以自己编译 Scrcpy。即使是在树莓派上，按照 ",-1)),t(e,{href:"https://github.com/Genymobile/scrcpy/blob/master/BUILD.md"},{default:a(()=>[...s[4]||(s[4]=[n("Scrcpy 的 GitHub 主页",-1)])]),_:1}),s[6]||(s[6]=n(" 上的说明来构建也不需要很长时间。",-1))]),s[38]||(s[38]=i("h3",{id:"设置手机",tabindex:"-1"},[n("设置手机 "),i("a",{class:"header-anchor",href:"#设置手机","aria-label":"Permalink to “设置手机”"},"​")],-1)),s[39]||(s[39]=i("p",null,"Scrcpy 安装好后，你必须启用 USB 调试并授权每个设备（你的树莓派、笔记本电脑或者工作站）为受信任的控制器。",-1)),i("p",null,[s[8]||(s[8]=n("打开安卓上的“设置”应用程序。如果“开发者选项”没有被激活，按照安卓的 ",-1)),t(e,{href:"https://developer.android.com/studio/debug/dev-options"},{default:a(()=>[...s[7]||(s[7]=[n("说明来解锁它",-1)])]),_:1}),s[9]||(s[9]=n("。",-1))]),s[40]||(s[40]=i("p",null,"接下来，启用“USB 调试”。",-1)),s[41]||(s[41]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/uploads/usb-debugging.jpg",alt:"Enable USB Debugging option",title:"Enable USB Debugging option"})],-1)),i("p",null,[s[11]||(s[11]=n("然后通过 USB 将手机连接到你的树莓派或者笔记本电脑（或者你正在使用的任何设备），如果可以选择的话，将模式设置为 ",-1)),t(e,{href:"https://en.wikipedia.org/wiki/Picture_Transfer_Protocol"},{default:a(()=>[...s[10]||(s[10]=[n("PTP",-1)])]),_:1}),s[12]||(s[12]=n("。如果你的手机不能使用 PTP，将你的手机设置为用于传输文件的模式（而不是，作为一个",-1)),s[13]||(s[13]=i("ruby",null,[n("叠接"),i("rt",null,"tethering")],-1)),s[14]||(s[14]=n("或者 MIDI 设备）。",-1))]),s[42]||(s[42]=p(`<p>你的手机可能会提示你授权你的电脑，这是通过它的 RSA 指纹进行识别的。你只需要在你第一次连接的时候操作即可，在之后你的手机会识别并信任你的计算机。</p><p>使用 <code>lsusb</code> 命令确认设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb</span></span>
<span class="line"><span>Bus 007 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span>
<span class="line"><span>Bus 011 Device 004: ID 046d:c21d Logitech, Inc. F310 Gamepad</span></span>
<span class="line"><span>Bus 005 Device 005: ID 0951:1666 Kingston Technology DataTraveler G4</span></span>
<span class="line"><span>Bus 005 Device 004: ID 05e3:0608 Genesys Logic, Inc. Hub</span></span>
<span class="line"><span>Bus 004 Device 001: ID 18d1:4ee6 Google Inc. Nexus/Pixel Device (PTP + debug)</span></span>
<span class="line"><span>Bus 003 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span>
<span class="line"><span>Bus 002 Device 001: ID 1d6b:0003 Linux Foundation 3.0 root hub</span></span>
<span class="line"><span>Bus 001 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span></code></pre></div><p>然后执行 <code>scrcpy</code> 以默认设置运行。</p><p><img src="https://opensource.com/sites/default/files/uploads/scrcpy-pi.jpg" alt="Scrcpy running on a Raspberry Pi" title="Scrcpy running on a Raspberry Pi"></p><p>性能和响应能力取决于你使用什么设备来控制你的手机。在树莓派派上，一些动画可能会变慢，甚至有时候会响应滞后。Scrcpy 提供了一个简单的解决办法：降低 Scrcpy 显示图像的位速率和分辨率使得你的计算机能够容易显示动画。使用以下命令来实现：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scrcpy --bit-rate 1M --max-size 800</span></span></code></pre></div>`,7)),i("p",null,[s[16]||(s[16]=n("尝试不同的值来找到一个适合你的值。为了使键入更方便，在选定一个命令之后，可以考虑 ",-1)),t(e,{href:"https://opensource.com/article/19/7/bash-aliases"},{default:a(()=>[...s[15]||(s[15]=[n("创建自己的 Bash 别名",-1)])]),_:1}),s[17]||(s[17]=n("。",-1))]),s[43]||(s[43]=p(`<h3 id="剪断连线" tabindex="-1">剪断连线 <a class="header-anchor" href="#剪断连线" aria-label="Permalink to “剪断连线”">​</a></h3><p>Scrcpy 开始运行后，你甚至可以通过 WiFi 连接你的手机和计算机。Scrcpy 安装过程也会安装 <code>adb</code>，它是一个与安卓设备通信的命令。Scrcpy 也可以使用这个命令与你的设备通信，<code>adb</code> 可以通过 TCP/IP 连接。</p><p><img src="https://opensource.com/sites/default/files/uploads/ssur-desktop.png" alt="Scrcpy running on a computer" title="Scrcpy running on a computer"></p><p>要尝试的话，请确保你的手机通过 WiFi 连在与你的计算机所使用的相同的无线网络上。依然不要断开你的手机与 USB 的连接！</p><p>接下来，通过手机中的“设置”，选择“关于手机”来获取你手机的 IP 地址。查看“状态”选项来获得你的地址。它通常是 192.168 或者 10 开头。</p><p>或者，你也可以使用 <code>adb</code> 来获得你手机的IP地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ adb shell ip route | awk &#39;{print $9}&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To connect to your device over WiFi, you must enable TCP/IP connections. This, you must do through the adb command:</span></span>
<span class="line"><span>$ adb tcpip 5555</span></span>
<span class="line"><span>Now you can disconnect your mobile from USB.</span></span>
<span class="line"><span>Whenever you want to connect over WiFi, first connect to the mobile with the command adb connect. For instance, assuming my mobile&#39;s IP address is 10.1.1.22, the command is:</span></span>
<span class="line"><span>$ adb connect 10.1.1.22:5555</span></span></code></pre></div><p>连接好之后，你就可以像往常一样运行 Scrcpy 了。</p><h3 id="远程控制" tabindex="-1">远程控制 <a class="header-anchor" href="#远程控制" aria-label="Permalink to “远程控制”">​</a></h3>`,9)),i("p",null,[s[19]||(s[19]=n("Scrcpy 很容易使用。你可以在终端或者 ",-1)),t(e,{href:"https://opensource.com/article/19/9/mirror-android-screen-guiscrcpy"},{default:a(()=>[...s[18]||(s[18]=[n("一个图形界面应用",-1)])]),_:1}),s[20]||(s[20]=n(" 中尝试它。",-1))]),s[44]||(s[44]=i("p",null,"你是否在使用其它的屏幕镜像工具？如果有的话，请在评论中告诉我们吧。",-1)),s[45]||(s[45]=i("hr",null,null,-1)),i("p",null,[s[22]||(s[22]=n("via: ",-1)),t(e,{href:"https://opensource.com/article/21/3/android-raspberry-pi"},{default:a(()=>[...s[21]||(s[21]=[n("https://opensource.com/article/21/3/android-raspberry-pi",-1)])]),_:1})]),i("p",null,[s[27]||(s[27]=n("作者：",-1)),t(e,{href:"https://opensource.com/users/sudeshna-sur"},{default:a(()=>[...s[23]||(s[23]=[n("Sudeshna Sur",-1)])]),_:1}),s[28]||(s[28]=n(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[24]||(s[24]=[n("lujun9972",-1)])]),_:1}),s[29]||(s[29]=n(" 译者：",-1)),t(e,{href:"https://github.com/ShuyRoy"},{default:a(()=>[...s[25]||(s[25]=[n("ShuyRoy",-1)])]),_:1}),s[30]||(s[30]=n(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[26]||(s[26]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[33]||(s[33]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[31]||(s[31]=[n("LCTT",-1)])]),_:1}),s[34]||(s[34]=n(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[32]||(s[32]=[n("Linux中国",-1)])]),_:1}),s[35]||(s[35]=n(" 荣誉推出",-1))])])}const S=l(u,[["render",b]]);export{T as __pageData,S as default};
